					Rigid->SetLinearImpulseVelocity(InLinearImpulse, bInvalidate);
				}
				else
				{
					Rigid->SetLinearImpulseVelocity(InLinearImpulse * Rigid->InvM(), bInvalidate);
				}
			}
		}
	});
